class Layout:
    """Offsets and sizes of STRUCTS for one pointer size."""

    def __init__(self, psize):
        self.psize = psize
        self.cache = {}

    def kind(self, k):
        """(size, align) of a field kind."""
        if k in ('ptr', 'word'):
            return self.psize, self.psize
        if k in STRUCTS:
            return self.struct(k)[1:]
        if 'x' in k:
            base, n = k.split('x')
            size, align = self.kind(base)
            return size * int(n), align
        return {'u8': (1, 1), 'u16': (2, 2), 'u32': (4, 4), 'i32': (4, 4), 'f32': (4, 4)}[k]

    def flat(self, name, prefix=''):
        """Fields of a structure with nested structures inlined: [(dotted name, kind)].
        A nested struct is not a C sub-struct: its fields are aligned one by one
        (in a 64-bit movie, the import count packs right after the frame time)."""
        out = []
        for fname, k in STRUCTS[name]:
            if k in STRUCTS:
                out += self.flat(k, prefix + fname + '.')
            else:
                out.append((prefix + fname, k))
        return out

    def struct(self, name):
        """(fields [(dotted name, kind, offset)], size, align)."""
        if name not in self.cache:
            off, align, fields = 0, 1, []
            for fname, k in self.flat(name):
                size, a = self.kind(k)
                off = (off + a - 1) // a * a
                fields.append((fname, k, off))
                off += size
                align = max(align, a)
            self.cache[name] = (fields, (off + align - 1) // align * align, align)
        return self.cache[name]


class Reader:
    """Typed reads with byte coverage tracking (to find structures we don't know)."""

    def __init__(self, data, endian, psize):
        self.d = data
        self.e = endian
        self.layout = Layout(psize)
        self.psize = psize
        self.cov = bytearray(len(data))

    def mark(self, off, n):
        self.cov[off:off + n] = b'\1' * n

    def scalar(self, k, off):
        fmt = {'u8': 'B', 'u16': 'H', 'u32': 'I', 'i32': 'i', 'f32': 'f',
               'ptr': 'I' if self.psize == 4 else 'Q', 'word': 'I' if self.psize == 4 else 'Q'}[k]
        size = struct.calcsize(fmt)
        self.mark(off, size)
        return struct.unpack_from(self.e + fmt, self.d, off)[0]

    def read(self, name, off):
        """A struct as a dict (nested structs and fN arrays expanded)."""
        fields, size, _ = self.layout.struct(name)
        out = {}
        for fname, k, foff in fields:
            if 'x' in k:
                base, n = k.split('x')
                bsize = self.layout.kind(base)[0]
                value = [self.scalar(base, off + foff + i * bsize) for i in range(int(n))]
            else:
                value = self.scalar(k, off + foff)
            *path, leaf = fname.split('.')
            node = out
            for p in path:
                node = node.setdefault(p, {})
            node[leaf] = value
        return out

    def size(self, name):
        return self.layout.struct(name)[1]

    def string(self, off):
        if off == 0:
            return None
        end = self.d.index(b'\0', off)
        self.mark(off, end + 1 - off)
        return self.d[off:end].decode('latin-1')

    def ptrs(self, lst):
        return [self.scalar('ptr', lst['ptr'] + i * self.psize) for i in range(lst['count'])]

    def array(self, name, lst):
        size = self.size(name)
        return [self.read(name, lst['ptr'] + i * size) for i in range(lst['count'])]


def parse_const(data, endian):
    if data.startswith(b'Apt constant file'):
        r = Reader(data, endian, 4)
        r.mark(0, 20)
        entry, count, _hsize = (r.scalar('u32', 20 + i * 4) for i in range(3))
        base, step, psize = 32, 8, 4
    elif data.startswith(b'Apt1'):
        r = Reader(data, endian, 8)
        r.mark(0, 24)
        entry, count, _hsize = (r.scalar('ptr', 24 + i * 8) for i in range(3))
        base, step, psize = 48, 16, 8
    else:
        raise ValueError('not an Apt const file')
    items = []
    for i in range(count):
        t = r.scalar('word', base + i * step)
        voff = base + i * step + psize
        if t == 1:
            v = r.string(r.scalar('ptr', voff))
        elif t == 6:
            v = r.scalar('f32', voff)
            r.mark(voff, psize)
        else:
            v = r.scalar('word', voff)
        items.append((t, v))
    return {'entry': entry, 'items': items, 'reader': r}


class Movie:
    def __init__(self, apt, const, endian=None):
        if not apt[:13] in (b'Apt Data:1:7:', b'Apt Data:1:8:'):
            raise ValueError('not an Apt 1.7/1.8 movie')
        psize = int(apt[13:14])
        if endian is None:  # the byte order in which the const entry offset lands on the movie
            endian = '<'
            for e in ('<', '>'):
                entry = struct.unpack_from(e + ('I' if psize == 4 else 'Q'), const,
                                           20 if psize == 4 else 24)[0]
                if entry + 2 * psize <= len(apt) and \
                        struct.unpack_from(e + 'I', apt, entry + psize)[0] == SIG:
                    endian = e
                    break
        self.endian, self.psize = endian, psize
        self.const = parse_const(const, endian)
        self.r = Reader(apt, endian, psize)
        self.r.mark(0, 16)
        self.code = {}
        self.chars = {}
        self.root = self.character(self.const['entry'])

    # characters
    def character(self, off):
        if off == 0:
            return None
        if off in self.chars:
            return self.chars[off]
        r = self.r
        hdr = r.read('header', off)
        if hdr['sig'] != SIG:
            raise ValueError(f'bad character signature at {off:#x}')
        kind = CHAR_TYPES.get(hdr['type'])
        if kind is None:
            raise NotImplementedError(f"character type {hdr['type']} at {off:#x}")
        ch = {'kind': kind, 'off': off, 'h1a': hdr['h1a'], 'h1b': hdr['h1b'], 'h2': hdr['h2']}
        self.chars[off] = ch
        ch.update(r.read(kind, off + r.size('header')))
        if kind in ('movie', 'sprite'):
            ch['frames'] = [[self.item(p) for p in r.ptrs(f)] for f in r.array('list', ch['frames'])]
        if kind == 'movie':
            ch['imports'] = [dict(i, movie=r.string(i['movie']), name=r.string(i['name']))
                             for i in r.array('import', ch['imports'])]
            ch['exports'] = [dict(e, name=r.string(e['name'])) for e in r.array('export', ch['exports'])]
            ch['chars'] = [self.character(p) if p != off else 'self' for p in r.ptrs(ch['chars'])]
        elif kind == 'text':
            ch['content'], ch['value'] = r.string(ch['content']), r.string(ch['value'])
        elif kind == 'font':
            ch['name'] = r.string(ch['name'])
